      tldr: {
        id: 'tldr',
        isTldr: true,
          snippetBlocks: [{ type: 'one-sentence', text: 'Mejores mini PCs AMD para LLMs locales en 2026: Minisforum MS-A2 ($1.599, 96 GB, 70B Q4), Beelink GTR9 Pro ($1.899, 128 GB, 70B Q5), GMKtec EVO-X2 ($2.199,99, 64 GB, tienda de EE. UU.) — todos con Ryzen AI Max+ 395 y memoria unificada; los precios del MS-A2 y del GTR9 Pro son informados y quedan un 25–50% por debajo del Mac Studio M5 Max (desde $2.499), mientras que el EVO-X2 es solo un 12% más barato.' }, { type: 'plain-terms', text: 'Los mini PCs AMD Ryzen AI Max+ 395 usan memoria unificada — como Apple Silicon, CPU, GPU y NPU comparten un único banco de memoria. ROCm es el stack de software de AMD equivalente a NVIDIA CUDA para frameworks LLM como vLLM u Ollama.' }],
        items: [
          'Mejor general: Minisforum MS-A2 ($1.599, 96 GB RAM). Ejecuta Llama 3.3 70B Q4 sin problemas. Mejor relación precio-rendimiento.',
          'Máxima RAM: Beelink GTR9 Pro ($1.899, 128 GB). Ejecuta 70B Q5 con ventanas de contexto masivas. Mejor para usuarios avanzados.',
          'Precio más bajo: Minisforum MS-A2 ($1.599, 96 GB, informado). El GMKtec EVO-X2 no es la opción económica: $2.199,99 con 64 GB en la tienda de EE. UU. de GMKtec (consultada el 2026-11-14, precio del fabricante), con un modelo de 128 GB a $3.499,99–3.649,99.',
          'Opción premium: AOOSTAR GEM12 Pro ($1.799, 96 GB). Puerto OCuLink para expansión eGPU. Enfocado en entusiastas.',
          'Los cuatro: Soporte ROCm en Linux (kernel 6.11+), RAM LPDDR5X de alta velocidad, SSD NVMe de 1 TB o más.',
          'Rendimiento: los cuatro usan el Ryzen AI Max+ 395 (NPU de 50 TOPS), así que el chip no los distingue; lo hacen el precio, el tamaño de memoria y la refrigeración.',
          'Vs Mac Studio M5 Max (actualización agosto 2026, desde $2.499): misma arquitectura de memoria unificada, aún 25–50% más barato. Compensación: macOS por Linux/ROCm.',
          'Estado de Linux: ROCm 6.2+ estable. Ollama, vLLM, MLX funcionan. Menos pulido que CUDA, pero listo para producción.',
        ],
      },
      'why-amd': {
        id: 'why-amd',
        title: 'Por qué importa AMD Ryzen AI Max+ para LLM local',
        content: 'AMD Ryzen AI Max+ se lanzó a finales de 2025 con una arquitectura radicalmente nueva para mini PCs de consumo. Esto es lo que lo hace relevante para los usuarios de LLM local.',
        items: [
          '**Memoria unificada como Apple Silicon:** Un pool de 64–128 GB compartido por CPU, iGPU y NPU. Sin cuello de botella entre VRAM y RAM. Los modelos permanecen en memoria rápida y la inferencia se mantiene ágil.',
          '**La iGPU rivaliza con GPUs discretas:** La Radeon 8060S (RDNA 3.5) ofrece cómputo equivalente a la RTX 4070 con una décima parte del consumo eléctrico. Llama 3.3 70B Q4 corre a 20–30 tok/s.',
          '**NPU de 50 TOPS:** Unidad de procesamiento neural dedicada que acelera operaciones cuantizadas. Notablemente más rápida para modelos INT8/Q4 comparado con CPU sola.',
          '**TDP de 65–120 W:** El sistema completo consume menos energía que una sola RTX 4090. Funciona con refrigeración pasiva o ventiladores silenciosos. No requiere fuente de 350 W.',
          '**El ecosistema ROCm madura:** El soporte en Linux es ahora estable (kernel 6.11+, ROCm 6.2+). Ollama, vLLM y LM Studio soportan la iGPU AMD de forma nativa.',
          '**Los OEMs chinos entregan rápido:** Minisforum (almacén en Alemania), AOOSTAR, Beelink y GMKtec llegan a EU/EE. UU. en 2–4 semanas.',
          '**Rango de precio $1.600–2.500 USD:** Supera al Mac Studio M5 Max ($2.499 de precio inicial tras la actualización de agosto de 2026) en un 25–50% mientras ofrece capacidad de memoria unificada idéntica o superior en el nivel de 128GB.',
        ],
      },
