          snippetBlocks: [{ type: 'one-sentence', text: 'Melhores mini PCs AMD para LLMs locais em 2026: Minisforum MS-A2 ($1.599, 96 GB, 70B Q4), Beelink GTR9 Pro ($1.899, 128 GB, 70B Q5), GMKtec EVO-X2 (US$ 2.199,99, 64 GB, loja americana) — todos com Ryzen AI Max+ 395 e memória unificada; os preços do MS-A2 e do GTR9 Pro são reproduzidos e ficam 25–50% abaixo do Mac Studio M5 Max (a partir de US$ 2.499), enquanto o EVO-X2 fica só cerca de 12% abaixo.' }, { type: 'plain-terms', text: 'Mini PCs AMD Ryzen AI Max+ 395 usam memória unificada — como Apple Silicon, CPU, GPU e NPU compartilham um único pool de memória. ROCm é a pilha de software AMD equivalente ao CUDA da NVIDIA para frameworks LLM como vLLM ou Ollama.' }],
