          'F: Wie laut sind diese Mini-PCs unter Last? | A: Minisforum 42dB, Beelink 44dB, AOOSTAR 40dB (Angaben übernommen, nicht von PromptQuorum gemessen). Für den GMKtec EVO-X2 haben wir keinen Wert gefunden; Notebookcheck nannte die 64GB-Variante vergleichsweise leise.',
